def invite(name, *friends, host="Pixel"):
    guests = [name, *friends]
    if len(guests) == 1:
        guest_text = guests[0]
    else:
        guest_text = ", ".join(guests[:-1]) + " and " + guests[-1]
    return f"{host} invites {guest_text} to the party!"

